#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <sys/syscall.h>
#include <sys/types.h>
#include <unistd.h>

/*
 * The command sandbox unshares the PID namespace but exposes the parent
 * namespace's /proc. Lean 4.22 constructs /proc/<getpid()>/exe, so the normal
 * namespace-local PID does not exist in the visible /proc. Return the outer
 * PID reported by /proc/self/status to restore that path lookup.
 */
pid_t getpid(void) {
    static pid_t outer_pid = 0;
    if (outer_pid != 0) {
        return outer_pid;
    }

    FILE *status = fopen("/proc/self/status", "r");
    if (status != NULL) {
        char *line = NULL;
        size_t capacity = 0;
        while (getline(&line, &capacity, status) != -1) {
            long parsed = 0;
            if (sscanf(line, "Pid:\t%ld", &parsed) == 1 && parsed > 0) {
                outer_pid = (pid_t)parsed;
                break;
            }
        }
        free(line);
        fclose(status);
    }

    if (outer_pid == 0) {
        outer_pid = (pid_t)syscall(SYS_getpid);
    }
    return outer_pid;
}

